// Login POST /api/auth/login —— 本地/LDAP 双路登录，下发 cookie。
func Login(ctx context.Context, c *app.RequestContext) {
	var req authpb.LoginRequest
	if err := c.BindAndValidate(&req); err != nil {
		c.String(consts.StatusBadRequest, err.Error())
		return
	}

	user, token, err := AuthSvc.Login(ctx, authservice.LoginCommand{
		Username: req.GetUsername(),
		Password: req.GetPassword(),
	})
	if err != nil {
		writeAuthError(c, err)
		return
	}

	// 下发 httpOnly cookie token（httpOnly, sameSite=Lax, maxAge=24h, path=/）。
	c.SetCookie("token", token, 24*3600, "/", "", protocol.CookieSameSiteLaxMode, false, true)

	c.JSON(consts.StatusOK, &authpb.LoginResponse{User: toApiUserDTO(user)})
}

// Logout POST /api/auth/logout —— 清除 cookie。
func Logout(ctx context.Context, c *app.RequestContext) {
	c.SetCookie("token", "", -1, "/", "", protocol.CookieSameSiteLaxMode, false, true)
	c.JSON(consts.StatusOK, &authpb.LogoutResponse{Success: true})
}

